tool_calls:
mkdir -p /home/eval/logs/out
export LC_ALL=C
work=$(mktemp -d)
awk 'BEGIN { FS=" "; OFS="\t" }
NF == 5 && $5 ~ /^[0-9]+(\.[0-9]+)?ms$/ {
    endpoint=$3
    sub(/\?.*$/, "", endpoint)
    if (endpoint ~ /^\/static\//) next
    if (endpoint != "/") sub(/\/$/, "", endpoint)
    if (endpoint == "/healthz") next
    latency=$5
    sub(/ms$/, "", latency)
    print endpoint, latency, ($4+0 >= 500 ? 1 : 0)
}' /home/eval/logs/access.log | sort -t $'\t' -k1,1 -k2,2n > "$work/requests.tsv"
awk 'BEGIN { FS=OFS="\t" }
function emit(    rank50,rank95) {
    if (!n) return
    rank50=int((n+1)/2)
    rank95=int((95*n+99)/100)
    printf "%s\t%d\t%.0f\t%.0f\t%d\n", endpoint,n,values[rank50],values[rank95],int(1000*errors/n)
}
$1 != endpoint { emit(); endpoint=$1; n=0; errors=0 }
{ values[++n]=$2; errors+=$3 }
END { emit() }
' "$work/requests.tsv" | sort -t $'\t' -k4,4nr -k2,2nr -k1,1 | head -n 5 > "$work/top.tsv"
{ printf 'endpoint\tcount\tp50\tp95\terr_permille\n'; cat "$work/top.tsv"; } > /home/eval/logs/out/report.tsv
rm -rf "$work"
cat /home/eval/logs/out/report.tsv

